// ObjetivosLista.js
import React from 'react';
import PropTypes from 'prop-types';

const ObjetivosLista = ({ objetivos }) => {
    if (objetivos.length === 0) {
        return <p>No tienes objetivos de ahorro registrados.</p>;
    }

    return (
        <ul>
            {objetivos.map((objetivo) => (
                <li key={objetivo.id}>
                    <strong>{objetivo.nombre}</strong>: ${objetivo.monto} en {objetivo.plazo} meses
                </li>
            ))}
        </ul>
    );
};

ObjetivosLista.propTypes = {
    objetivos: PropTypes.arrayOf(
        PropTypes.shape({
            id: PropTypes.string.isRequired,
            nombre: PropTypes.string.isRequired,
            monto: PropTypes.number.isRequired,
            plazo: PropTypes.number.isRequired,
        })
    ).isRequired,
};

export default ObjetivosLista;
